-- 665K employer applications for foreign workers -- H-1B, PERM, H-2A/B -- with employer, job, wage, and outcome.
-- Auto-generated by scripts/gen_evidence_pages.py: 664,616 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("DECISION_DATE") as year, count(*) as records
from THE_LIBRARY.IMMIGRATION.FOREIGN_WORKER_VISA_APPLICATIONS
where "DECISION_DATE" is not null
group by 1
order by 1
